            .foregroundStyle(color)
            .padding(.horizontal, fill == nil ? 12 : 14)
            .frame(minWidth: fill == nil ? 44 : 34, minHeight: 34)
            .background { if let fill { Capsule().fill(fill) } }
            .frame(minWidth: 44, minHeight: 44)
